// Wick
// A precision platformer: Wick, a candle flame, runs, jumps and wall-jumps through one-screen rooms to light the lantern
// in each (docs/carts/wick.md). Step 1: his movement, the rooms from the ROM, death and the instant restart.

// --- Colours: the default palette (DawnBringer 16). The overlay's index 0 is transparent. ---

const SHADOW = 1, PANEL = 3, RED = 6, DIM = 10, GREEN = 11, CYAN = 13, GOLD = 14, WHITE = 15;

// --- Art: made by art.py (tiles.txt, palette.txt, map.txt). The block below is rewritten each time it runs. ---

// ART (generated by art.py: do not edit)
const ART = {
  tiles: {},
  sprites: {"ember": {"pal": 0, "size": 8, "tile": 518}, "puff": {"pal": 0, "size": 16, "tile": 516}, "wick0": {"pal": 0, "size": 16, "tile": 512}, "wick1": {"pal": 0, "size": 16, "tile": 514}},
  scenes: {"cells": {"h": 2, "mx": 40, "my": 0, "pal": 1, "w": 10}, "logo": {"h": 5, "mx": 0, "my": 30, "pal": 3, "w": 32}, "wall": {"h": 26, "mx": 64, "my": 0, "pal": 2, "w": 32}},
  colors: {"GLASS": 200},
};
// END ART
/** Queue one of ART.sprites at (x, y), above the background; opts as for spr (fx, fy ...). */
function sprite(s, x, y, opts = {}) { spr(s.tile, x, y, { size: s.size, pal: s.pal, prio: 3, ...opts }); }

// --- Sound (SPEC 5). Songs use channels 0 to 5; effects take turns on 6 and 7. ---

const SFX = { move: 0, select: 1, pause: 2, hit: 3, over: 4, point: 5, record: 6 };
const SONG = { title: 0, play: 1 };
const SFX_CH = [7, 6];
let fxNext = 0;
function fx(n) { sfx(n, SFX_CH[fxNext]); fxNext ^= 1; }
let playing = -1;
/** A song is only started if it is not already playing (so a death does not restart the music). */
function play(song) { if (song === playing) return; playing = song; music(song); }

// --- Save slots (SPEC 13) ---

const VERSION_SLOT = 0, SAVE_VERSION = 1;

// --- Input: edge-triggered presses (btnp repeats; menus want one press) ---

let inputMask = 0, prevMask = 0;
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, X, Y, L, R, START, SELECT];
function readPad() { let m = 0; for (const b of BUTTONS) if (btn(b)) m |= 1 << b; return m; }
const pressed = (b) => (inputMask & (1 << b)) !== 0 && (prevMask & (1 << b)) === 0;

// --- The rooms (rooms.py packs rooms.txt into the ROM): 16 x 13 cells of 16 px, under the HUD strip ---

const COLS = 16, ROWS = 13, CELL = 16, ROOM_Y = 16;
const AIR = 0, STONE = 1, LEDGE = 2, WATER = 3, START_CELL = 4, LANTERN = 5, EMBER = 6;
let ROOMS = [];
function loadRooms() {
  const b = rom('rooms'); let at = 1;
  ROOMS = [];
  for (let k = 0; k < b[0]; k++) {
    const world = b[at], n = b[at + 1], par = b[at + 2] | (b[at + 3] << 8), len = b[at + 4];
    let name = ''; for (let i = 0; i < len; i++) name += String.fromCharCode(b[at + 5 + i]);
    at += 5 + len;
    const cells = Array.from(b.slice(at, at + COLS * ROWS)); at += COLS * ROWS;
    const s = cells.indexOf(START_CELL), l = cells.indexOf(LANTERN);
    ROOMS.push({ world, n, par, name, cells, sx: (s % COLS) * CELL + 3, sy: Math.floor(s / COLS) * CELL + 4, lx: l % COLS, ly: Math.floor(l / COLS) });
  }
}
/** The cell at column cx, row cy of a room: beyond the sides and the top is stone, below the bottom is air (a fall). */
const cellAt = (R, cx, cy) => (cx < 0 || cx >= COLS || cy < 0 ? STONE : cy >= ROWS ? AIR : R.cells[cy * COLS + cx]);

// --- Wick's movement (spec section 5): positions in pixels, speeds in pixels a frame. Pure: stepWick(w, pad, R)
// changes only w, so the tests and the solver play rooms with it as the game does. ---

const T = {
  w: 10, h: 12,                    // his body (the flame above it touches nothing)
  walk: 1.5, run: 2.6,             // top speeds
  accG: 0.30, accA: 0.20, stop: 0.40, drift: 0.05,   // speeding up on the ground and in the air; stopping; slowing in the air
  grav: 0.30, gravHold: 0.156,     // gravity; while A is held and he is rising (the higher jump)
  fall: 4.5, slide: 1.0,           // the fastest fall; on a wall he is pressing towards
  jump: -3.4,                      // about 2.3 cells held, 1.2 tapped
  coyote: 6, buffer: 8,            // frames a jump still works after an edge; frames a press is remembered (a press 6 frames
                                   // before the frame he lands on jumps on the frame after it)
  wjx: 2.6, wjy: -3.2, lock: 9,    // a wall jump: away and up; frames the d-pad cannot turn him back
  restart: 20,                     // frames from a death to the room again
};
const PAD_L = 1, PAD_R = 2, PAD_A = 4, PAD_B = 8;
const towards = (v, to, by) => (v < to ? Math.min(to, v + by) : Math.max(to, v - by));
/** Wick at a room's start. */
const newWick = (R) => ({ x: R.sx, y: R.sy, vx: 0, vy: 0, ground: true, wall: 0, coy: 0, buf: 0, lock: 0, a: 0, face: 1, dead: false, won: false, ember: false, ev: '' });
/** Is the body at (x, y) in stone? */
function inStone(R, x, y) {
  // (the pixels his body covers, however little of the last one: he never sinks a fraction into stone)
  const x0 = Math.floor(x / CELL), x1 = Math.floor((Math.ceil(x + T.w) - 1) / CELL), y0 = Math.floor(y / CELL), y1 = Math.floor((Math.ceil(y + T.h) - 1) / CELL);
  for (let cy = y0; cy <= y1; cy++) for (let cx = x0; cx <= x1; cx++) if (cellAt(R, cx, cy) === STONE) return true;
  return false;
}
/** One frame of Wick. pad: PAD_L, PAD_R, PAD_A, PAD_B. Sets w.ev to 'jump', 'walljump' or 'land' when that happened. */
function stepWick(w, pad, R) {
  w.ev = '';
  if (w.dead || w.won) return w;
  const a = pad & PAD_A ? 1 : 0, press = a && !w.a;
  w.a = a;
  if (press) w.buf = T.buffer; else if (w.buf) w.buf--;
  let dir = (pad & PAD_R ? 1 : 0) - (pad & PAD_L ? 1 : 0);
  if (w.lock) { w.lock--; if (dir && dir !== Math.sign(w.vx)) dir = 0; }
  if (dir) { w.vx = towards(w.vx, dir * (pad & PAD_B ? T.run : T.walk), w.ground ? T.accG : T.accA); w.face = dir; }
  else w.vx = towards(w.vx, 0, w.ground ? T.stop : T.drift);
  // a jump: from the ground (or just after it), else off a wall
  if (w.buf && (w.ground || w.coy)) { w.vy = T.jump; w.buf = 0; w.coy = 0; w.ground = false; w.ev = 'jump'; }
  else if (w.buf && w.wall && !w.ground) { w.vy = T.wjy; w.vx = -w.wall * T.wjx; w.face = -w.wall; w.lock = T.lock; w.buf = 0; w.ev = 'walljump'; }
  w.vy += a && w.vy < 0 ? T.gravHold : T.grav;
  w.vy = Math.min(w.vy, w.wall && dir === w.wall && !w.ground ? T.slide : T.fall);
  // across, a pixel at a time at most, stopping at stone
  let left = w.vx;
  while (left) {
    const s = Math.abs(left) > 1 ? Math.sign(left) : left;
    if (inStone(R, w.x + s, w.y)) { w.x = s > 0 ? Math.ceil(w.x) : Math.floor(w.x); if (inStone(R, w.x, w.y)) w.x -= Math.sign(s); w.vx = 0; break; }
    w.x += s; left -= s;
  }
  // down or up: stone stops him; a ledge only when he comes down onto its top
  const was = w.ground, bottom = w.y + T.h;
  w.ground = false;
  left = w.vy;
  while (left) {
    const s = Math.abs(left) > 1 ? Math.sign(left) : left, ny = w.y + s;
    let hit = inStone(R, w.x, ny);
    if (!hit && s > 0) { // a ledge under his feet: its top is the top of its cell
      const cy = Math.floor((Math.ceil(ny + T.h) - 1) / CELL), top = cy * CELL;
      if (w.y + T.h <= top && ny + T.h > top) for (let cx = Math.floor(w.x / CELL); cx <= Math.floor((w.x + T.w - 1) / CELL); cx++) if (cellAt(R, cx, cy) === LEDGE) hit = true;
    }
    if (hit) {
      if (s > 0) { w.y = Math.floor((Math.ceil(ny + T.h) - 1) / CELL) * CELL - T.h; w.ground = true; if (!was && w.vy > 1.5) w.ev = w.ev || 'land'; }
      else w.y = (Math.floor(ny / CELL) + 1) * CELL; // his head under the stone
      w.vy = 0; break;
    }
    w.y = ny; left -= s;
  }
  if (was && !w.ground && w.vy >= 0) w.coy = T.coyote; else if (w.coy) w.coy--;
  // a wall beside him, in the air: stone a pixel to the left or the right
  w.wall = w.ground ? 0 : inStone(R, w.x + 1, w.y) ? 1 : inStone(R, w.x - 1, w.y) ? -1 : 0;
  // what he touches: water and the fall below the room snuff him out; the lantern clears the room; an ember is picked up
  const x0 = Math.floor((w.x + 1) / CELL), x1 = Math.floor((w.x + T.w - 2) / CELL), y0 = Math.floor((w.y + 1) / CELL), y1 = Math.floor((w.y + T.h - 2) / CELL);
  for (let cy = y0; cy <= y1; cy++) for (let cx = x0; cx <= x1; cx++) {
    const c = cellAt(R, cx, cy);
    if (c === WATER) w.dead = true; else if (c === LANTERN) w.won = true; else if (c === EMBER) w.ember = true;
  }
  if (w.y > ROWS * CELL) w.dead = true;
  return w;
}

// --- State ---

let skipTitle = false; // tests set this to land straight in the first room
let state = 'title', paused = false, timer = 0, clock = 0;
let titleSel = 0, pauseSel = 0;
let room = 0, cur = null, wick = null; // the room's number, the room, Wick
let frames = 0, started = false, deaths = 0, deadFor = 0, wonFor = 0, lit = false;

function init() {
  if (dget(VERSION_SLOT) !== SAVE_VERSION) { for (let i = 0; i < 256; i++) dset(i, 0); dset(VERSION_SLOT, SAVE_VERSION); }
  loadRooms();
  // Layers: the room's cells on layer 1 (written into Map RAM by drawRoom), the far wall behind it on layer 2, the
  // title's lettering on layer 0 (shown only on the title)
  const wl = ART.scenes.wall, lg = ART.scenes.logo;
  bg(1, { mx: 0, my: 0, mw: COLS * 2, mh: ROWS * 2, x: 0, y: -ROOM_Y, wrap: false, show: true });
  bg(2, { mx: wl.mx, my: wl.my, mw: wl.w, mh: wl.h, x: 0, y: -ROOM_Y, wrap: false, show: true });
  bg(0, { mx: lg.mx, my: lg.my, mw: lg.w, mh: lg.h, x: 0, y: -40, wrap: false, show: false });
  blend({ layers: ['overlay'], half: true }); // overlay colours from 192 up (ART.colors.GLASS) are see-through
  color(0, 1, 1, 3);
  if (skipTitle) startRoom(0); else toTitle();
}

function toTitle() { state = 'title'; timer = 0; titleSel = 0; paused = false; startRoomPicture(0); play(SONG.title); }

/** Write a room's cells into Map RAM: each cell is four tiles of its picture in ART.scenes.cells. */
const CELL_ART = { [STONE]: 0, [LEDGE]: 1, [WATER]: 2, [LANTERN]: 3 };
function drawRoom(Rm, lanternLit) {
  const c = ART.scenes.cells;
  for (let cy = 0; cy < ROWS; cy++) for (let cx = 0; cx < COLS; cx++) {
    const kind = Rm.cells[cy * COLS + cx];
    const k = kind === LANTERN && lanternLit ? 4 : CELL_ART[kind];
    for (let j = 0; j < 2; j++) for (let i = 0; i < 2; i++) mset(cx * 2 + i, cy * 2 + j, k === undefined ? 0 : mget(c.mx + k * 2 + i, c.my + j));
  }
}
function startRoomPicture(n) { cur = ROOMS[n]; drawRoom(cur, false); wick = newWick(cur); }
/** Begin (or begin again) room n: Wick at its start, the clock at nothing until he first moves. */
function startRoom(n, keepDeaths = false) {
  room = n; startRoomPicture(n);
  frames = 0; started = false; deadFor = 0; wonFor = 0; lit = false; paused = false; timer = 0; state = 'play';
  if (!keepDeaths) deaths = 0;
  play(SONG.play);
}

// --- Update ---

function update() {
  inputMask = readPad(); clock++;
  if (!paused) timer++;
  if (paused) updatePause();
  else if (state === 'title') updateTitle();
  else if (state === 'play') updatePlay();
  prevMask = inputMask;
}

function updateTitle() {
  if (pressed(A) || pressed(START)) { fx(SFX.select); startRoom(0); }
}

/** The buttons as stepWick takes them. */
const padOf = (m) => (m & (1 << LEFT) ? PAD_L : 0) | (m & (1 << RIGHT) ? PAD_R : 0) | (m & (1 << A) ? PAD_A : 0) | (m & (1 << B) ? PAD_B : 0);

function updatePlay() {
  if (pressed(START)) { paused = true; pauseSel = 0; fx(SFX.pause); return; }
  if (wick.dead) { if (++deadFor >= T.restart) startRoom(room, true); return; }
  if (wick.won) { if (++wonFor >= 50) { if (room + 1 < ROOMS.length) startRoom(room + 1); else toTitle(); } return; }
  if (pressed(SELECT)) { startRoom(room, true); return; }
  const pad = padOf(inputMask);
  if (pad) started = true;
  if (started) frames++;
  stepWick(wick, pad, cur);
  if (wick.ev === 'jump' || wick.ev === 'walljump') fx(SFX.move);
  if (wick.dead) { deaths++; fx(SFX.hit); }
  if (wick.won) { lit = true; drawRoom(cur, true); fx(SFX.record); }
}

function updatePause() {
  if (pressed(START) || pressed(B)) { paused = false; return; }
  if (pressed(UP)) { pauseSel = (pauseSel + 2) % 3; fx(SFX.move); }
  if (pressed(DOWN)) { pauseSel = (pauseSel + 1) % 3; fx(SFX.move); }
  if (pressed(A)) {
    fx(SFX.select);
    if (pauseSel === 0) paused = false;
    else if (pauseSel === 1) startRoom(room, true);
    else toTitle();
  }
}

// --- Draw ---

function draw() {
  cls();
  bg(0, { show: state === 'title' });
  if (state === 'play') drawPlay(); else drawTitle();
  if (paused) drawPause();
}

const clockText = (f) => `${Math.floor(f / 3600)}:${String(Math.floor(f / 60) % 60).padStart(2, '0')}.${Math.floor((f % 60) / 6)}`;

function drawWick() {
  if (wick.dead) { if (deadFor < 12) sprite(ART.sprites.puff, wick.x - 3, ROOM_Y + wick.y - 4 - deadFor / 2); return; }
  sprite(clock % 16 < 8 ? ART.sprites.wick0 : ART.sprites.wick1, wick.x - 3, ROOM_Y + wick.y - 4, { fx: wick.face < 0 });
}

function drawPlay() {
  drawWick();
  rectfill(0, 0, 256, ROOM_Y, SHADOW);
  txt(`${cur.world}-${cur.n}`, 6, 4, GOLD);
  txt(clockText(frames), 100, 4, WHITE);
  txt(`DEATHS ${deaths}`, 176, 4, deaths ? RED : DIM);
  if (wick.won && wonFor > 10) { panel(64, 96, 128, 30); ctxt('LIT!', 102, GOLD); ctxt(clockText(frames), 114, WHITE); }
}

function drawTitle() {
  drawWick();
  panel(40, 132, 176, 40);
  ctxt('A: PLAY', 140, WHITE);
  ctxt('A CANDLE IN THE DARK', 156, CYAN);
}

function drawPause() {
  panel(64, 72, 128, 76);
  ctxt('PAUSED', 80, GOLD);
  ['RESUME', 'RESTART ROOM', 'QUIT TO TITLE'].forEach((s, i) => txt(`${i === pauseSel ? '> ' : '  '}${s}`, 76, 98 + i * 14, i === pauseSel ? WHITE : DIM));
}

function panel(x, y, w, h) { rectfill(x, y, w, h, ART.colors.GLASS); rect(x, y, w, h, PANEL); }
function txt(s, x, y, c) { print(s, x + 1, y + 1, SHADOW); print(s, x, y, c); }
const ctxt = (s, y, c) => txt(s, 128 - s.length * 4, y, c);
